        meera_trend:_FillValue = 9.96921e+37f ;

// global attributes:
        string :creation_date = "Tue Jun  9 15:07:55 AEST 2015" ;
        string :source_file = "trend_djf_Mawson.nc" ;
        string :title = "NCL generated netCDF file with multiple unlimited dimensions" ;
